entries[71714] = { ["name"] = "Formel: Umhang - Geringe Beweglichkeit", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man die Verzauberung 'Geringe Beweglichkeit' durchführt.\nEinen Umhang dauerhaft verzaubern, sodass die Beweglichkeit um 2 erhöht wird. Kann nicht auf Gegenstände über Stufe 376 angewandt werden.\nBenötigt Klassische Verzauberkunst (225)\nVerkaufspreis:" }
entries[71715] = { ["name"] = "Abhandlung zu strategischem Vorgehen", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Anduin Lothars ultimatives Kompendium der Kampfstrategien. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71716] = { ["name"] = "Wahrsagerrunen", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Ein altes Sortiment geschnitzter Wahrsagerrunen. Professor Thaddeus Paleo vom Dunkelmond-Jahrmarkt wäre bestimmt daran interessiert.\"" }
entries[71718] = { ["name"] = "Schneller Strandschreiter", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbaren schnellen Strandschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Eine Seltenheit bei den Weitschreiterarten von Kalimdor, die man leicht an ihrem durchdringenden Geruch von abgestorbenem Tang erkennt.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[71720] = { ["name"] = "Drachenbalgbeinrüstung", ["text"] = "Benutzen: Bringt dauerhaft eine Drachenbalgrüstung an einer Hose an, die die Ausdauer um 3 und das Ausweichen um 4 erhöht.\n\nKann nur auf Beinrüstungen in Eurem Inventar angewandt werden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden." }
entries[71721] = { ["name"] = "Muster: Drachenbalgbeinrüstung", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Herstellung von Drachenbalgbeinrüstung.\nBenötigt Lederverarbeitung des Kataklysmus (75)\n\nDrachenbalgbeinrüstung\nBenutzen: Bringt dauerhaft eine Drachenbalgrüstung an einer Hose an, die die Ausdauer um 3 und das Ausweichen um 4 erhöht.\n\nKann nur auf Beinrüstungen in Eurem Inventar angewandt werden. Kann nicht auf Gegenstände über Stufe 320 angewandt werden.\nBenötigt Makelloser Balg , Flüchtige Erde (20)" }
entries[71726] = { ["name"] = "Murkys kleiner Seelenstein", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Lehrt Euch, wie man Murkablo beschwört.\nMit Rechtsklick Murkablo beschwören oder wieder freigeben.\n80 ( 80)" }
