entries[71949] = { ["name"] = "Foliant der brennenden Juwelen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Entdeckt ein zufälliges episches Edelsteinrezept der Cataclysm-Stufe.\nBenötigt Juwelierskunst des Kataklysmus\n(75)" }
entries[71950] = { ["name"] = "Unwuchtiger Wurfring", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Erhaltet Zugang zu 10 unausgewuchteten Wurfringen. Wenn Ihr die Ringwurfbude verlasst, werden alle verbleibenden Ringe gelöscht.\n\"Keiner der Ringe ist richtig ausbalanciert.\"" }
entries[71951] = { ["name"] = "Banner der Gefallenen", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Beweis Eures Kampfesmuts. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71952] = { ["name"] = "Erobertes Insigne", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Von einem bezwungenen Feind errungen. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71953] = { ["name"] = "Tagebuch eines gefallenen Abenteurers", ["text"] = "Dieser Gegenstand startet eine Quest.\n\"Das Tagebuch enthält die Erzählungen der epischen Abenteuer eines gefallenen Feindes. Jemand vom Dunkelmond-Jahrmarkt würde es sicherlich gern erwerben.\"" }
entries[71954] = { ["name"] = "Zwielichtdrache des ruchlosen Gladiators", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Das ist ein Flugreittier.\nBeschwört einen reitbaren Zwielichtdrachen des ruchlosen Gladiators oder gibt ihn wieder frei. Das ist ein Flugreittier.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Helden, die ihre Macht während des Kataklysmus als Gladiatoren unter Beweis gestellt haben, haben die außergewöhnlichsten Vertreter der Zwielichtdrachenart erhalten.\"\nKlassisch" }
entries[71955] = { ["name"] = "Rezept: Tiefenheim-Iolith transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation eines Tiefenheim-Ioliths.\nBenötigt Alchemie des Kataklysmus\n(75)" }
entries[71956] = { ["name"] = "Rezept: Elfenperidot transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation eines Elfenperidots.\nBenötigt Alchemie des Kataklysmus\n(75)" }
entries[71957] = { ["name"] = "Rezept: Lichtgemme transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation einer Lichtgemme.\nBenötigt Alchemie des Kataklysmus\n(75)" }
entries[71958] = { ["name"] = "Rezept: Lavakoralle transmutieren", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch die Transmutation einer Lavakoralle.\nBenötigt Alchemie des Kataklysmus\n(75)" }
