entries[72110] = { ["name"] = "Ramponierter Schraubenschlüssel", ["text"] = "Questgegenstand\nBenutzen: Repariert den beschädigten Dampfpanzer im Areal des Dunkelmond-Jahrmarkts.\n\"Ein altes, abgenutztes Werkzeug, mit dem hunderte Dampfpanzer repariert wurden.\"" }
entries[72111] = { ["name"] = "Trockene Hartriegelwurzel", ["text"] = "Questgegenstand\n\"Bemerkenswert trocken und sicherlich äußerst brennbar.\"" }
entries[72112] = { ["name"] = "Flatternde Brise", ["text"] = "Questgegenstand\nEinzigartig\n\"Je fester Ihr zupackt, desto mehr versucht sie Euch zu entwischen.\"" }
entries[72118] = { ["name"] = "Klaue des Eindringlings", ["text"] = "Questgegenstand\nEinzigartig\n\"Weitaus größer als jede Klaue, die Ihr je gesehen habt.\"" }
entries[72119] = { ["name"] = "Das Auge des Sklaventreibers", ["text"] = "Questgegenstand\nEinzigartig\n\"Leuchtet in einem kränklichen Gelb.\"" }
entries[72120] = { ["name"] = "Nebelberührtes Leder", ["text"] = "Handwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kürschnerei ausüben. Kann im Auktionshaus verkauft und erworben werden.\"\nVerkaufspreis:" }
entries[72125] = { ["name"] = "Schnell wachsende Schuppe", ["text"] = "Questgegenstand\n\"Nichts sollte so schnell wachsen.\"" }
entries[72126] = { ["name"] = "Pandemonius' Essenz", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein tiefer Blick in das Zentrum der wirbelnden Dunkelheit enthüllt nur weiteres Dunkel.\"" }
entries[72127] = { ["name"] = "Tavaroks Herz", ["text"] = "Questgegenstand\nEinzigartig\n\"Viel leichter, als man erwarten würde.\"" }
entries[72133] = { ["name"] = "Obstgartenwerkzeug", ["text"] = "Questgegenstand\nEinzigartig (6)\n\"Keine besonders gute Waffe, aber besser als nichts.\"" }
