entries[72140] = { ["name"] = "Schneller Waldschreiter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbaren schnellen Waldschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese farbenfrohe Rasse findet man nur in den Wäldern der Dunkelmond-Insel.\"\nVerkäufer:\nLhara\nZone:\nDunkelmond-Insel\nKosten:\n180" }
entries[72145] = { ["name"] = "Schneller Frühlingsschreiter", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbaren schnellen Frühlingsschreiter oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die Freuden des Nobelgartenfests kann man am besten genießen, wenn man diese treue, liebe und langweilig gefärbte Laune der Natur bei sich hat.\"\nVerkäufer:\nNobelgartenhändler\nZone:\nDurotar, Immersangwald, Mulgore, Tirisfal, Azurmythosinsel,\nDun Morogh, Wald von Elwynn, Teldrassil\nKosten:\n500" }
entries[72146] = { ["name"] = "Schneller Blumenstrauß", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbaren schnellen Blumenstrauß oder gibt ihn wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Wolle Rose kaufe?\"\nWeltereignis:\nLiebe liegt in der Luft\n\nVerkäufer:\nReizende Verkäuferin (Allianz)\nZone:\nSturmwind\nKosten:\n270\n\nVerkäufer:\nReizende Verkäuferin (Horde)\nZone:\nOrgrimmar\nKosten:\n270" }
