entries[72162] = { ["name"] = "Sha-berührtes Leder", ["text"] = "Benutzen: Läutert fünf Sha-Lederfetzen, um ein Stück nebelberührtes Leder zu erzeugen.\nBenötigt Kürschnerei (1)\nHandwerksmaterial\n\"Durch die Präsenz des Sha wurde dieses Leder seiner natürlichen Stärke und Widerstandskraft beraubt. Nur mehrere miteinander kombinierte Stücke haben eine Chance, diesen unbrauchbaren Balg zu verwerten.\"\nVerkaufspreis:" }
