entries[72480] = { ["name"] = "Kobaltauge", ["text"] = "Questgegenstand\n\"Bei Berührung eiskalt.\"" }
entries[72574] = { ["name"] = "Verstrahltes Zahnrad", ["text"] = "Questgegenstand\nEinzigartig\n\"Warnung: Anhaltende Exposition kann zu unerwünschten Effekten führen, Tod nicht ausgeschlossen.\"" }
entries[72575] = { ["name"] = "Weißes Reitkamel", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört ein reitbares weißes Reitkamel oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"An einem einzigen Nachmittag hat Fennimore Quigley als Erster ein Kamel gemolken und kurz darauf auch noch den Rekord für den längsten unbeabsichtigten Flug gebrochen.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[72578] = { ["name"] = "Nektarhauchmost", ["text"] = "Questgegenstand\nBenutzen: Spuckt einen Mundvoll Apfelmost aus. (3 Sek. Abklingzeit)\n\"Klebrig, süß und trüb. Diese alkoholfreie Variante des berühmten lokalen Apfelweins ist für Kinder und zur Bekämpfung von Bränden gleichermaßen geeignet.\"" }
entries[72582] = { ["name"] = "Verderbter Hippogryph", ["text"] = "Einzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\nBeschwört einen reitbaren verderbten Hippogryphen oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Die traurige Wahrheit ist, dass selbst ein weiser und majestätischer Hippogryph zu einem Opfer der Verderbtheit werden kann.\"\nVerkäufer:\nLandro Fernblick\nOrt:\nBeutebucht" }
entries[72583] = { ["name"] = "Huos Opfergaben", ["text"] = "Questgegenstand\nBenutzen: Fächelt Huo, dem Geist des Feuers, Luft zu. (15 Sek. Abklingzeit)" }
entries[72589] = { ["name"] = "Reife Orange", ["text"] = "Questgegenstand\n\"Platzt beinahe vor Saft. Kein Wunder, dass die Waldgeister hinter ihnen her waren.\"" }
entries[72597] = { ["name"] = "O'mroggs Kriegstuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Mit dem Blut seiner Feinde gefärbt.\"" }
